    @Override public void onEnable() {
        saveDefaultConfig(); migrateConfig(); pickaxeKey = new NamespacedKey(this, "special_pickaxe"); shovelKey = new NamespacedKey(this, "special_shovel"); axeKey = new NamespacedKey(this, "special_axe"); wandKey = new NamespacedKey(this, "selection_wand"); ownerKey = new NamespacedKey(this, "tool_owner");
        playersFile = new File(getDataFolder(), "players.yml"); minesFile = new File(getDataFolder(), "mines.yml");
        playersData = YamlConfiguration.loadConfiguration(playersFile); minesData = YamlConfiguration.loadConfiguration(minesFile);
        langFile = new File(getDataFolder(), "lang.yml");
        if (!langFile.exists()) saveResource("lang.yml", false);
        lang = YamlConfiguration.loadConfiguration(langFile);
        loadMines(); loadStats();
        if (Bukkit.getPluginManager().getPlugin("Vault") != null) {
            RegisteredServiceProvider<Economy> rsp = Bukkit.getServicesManager().getRegistration(Economy.class);
            if (rsp != null) economy = rsp.getProvider();
        }
        for (String cmd : List.of("mineadmin", "kopalnia", "kilof", "lopata", "siekiera", "prestiz", "mineprogress", "schowaj", "wyciagnij")) { if (getCommand(cmd) != null) { getCommand(cmd).setExecutor(this); getCommand(cmd).setTabCompleter(this); } }
        Bukkit.getPluginManager().registerEvents(this, this);
        startVisualTasks();
        if (Bukkit.getPluginManager().getPlugin("PlaceholderAPI") != null) new MineExpansion().register();
        getLogger().info("MineProgress 0.9.1 wlaczony (Paper 1.21.11 / Java 21).");
    }
    private void migrateConfig() {
        // Migrate existing 0.4.x configs: otherwise their old max level of 100 would override new defaults.
        if (getConfig().contains("settings.pickaxe-xp-per-level") && !getConfig().contains("settings.pickaxe-xp-base")) {
            getConfig().set("settings.max-pickaxe-level", 20);
            getConfig().set("settings.pickaxe-xp-base", 10);
            getConfig().set("settings.pickaxe-xp-increase-per-level", 2);
            getConfig().set("settings.pickaxe-xp-per-level", null);
            getLogger().info("Przeniesiono konfigurację progresji kilofa na system 0.5.0 (20 poziomów, rosnące wymagania XP).");
        }
        if (getConfig().contains("settings.player-xp-per-level") && !getConfig().contains("settings.player-xp-base")) { getConfig().set("settings.player-xp-base", getConfig().getLong("settings.player-xp-per-level", 100)); }
        if (!getConfig().getBoolean("settings.balance-tuning-0-7-0", false)) {
            getConfig().set("settings.prestige-bonus-per-level", 0.005);
            getConfig().set("settings.pickaxe-prestige-money-bonus", 0.0025);
            getConfig().set("settings.player-level-money-bonus", 0.001);
            getConfig().set("fortune.bonus-chance-per-level", 0.02);
            getConfig().set("fortune.double-drop-chance", 0.10);
            getConfig().set("mining-streak.blocks-per-step", 20);
            getConfig().set("mining-streak.money-bonus-per-step", 0.005);
            getConfig().set("mining-streak.max-bonus", 0.05);
            getConfig().set("settings.balance-tuning-0-7-0", true);
        }
        getConfig().options().copyDefaults(true);
        saveConfig();
    }
    @Override public void onDisable() { saveStats(); saveMines(); regenTasks.values().forEach(BukkitTask::cancel); if(boundaryTask!=null)boundaryTask.cancel(); if(hologramTask!=null)hologramTask.cancel(); for(Mine m:mines.values())removeHolograms(m); }

    private void loadStats() {
        ConfigurationSection root = playersData.getConfigurationSection("players"); if (root == null) return;
        for (String id : root.getKeys(false)) try {
            ConfigurationSection s = root.getConfigurationSection(id); if (s == null) continue;
            Stats st = new Stats(); st.level=s.getInt("level",1); st.xp=s.getLong("xp",0); st.pickLevel=Math.min(s.getInt("pickLevel",0),getConfig().getInt("settings.max-pickaxe-level",20)); st.pickXp=s.getLong("pickXp",0); st.prestige=s.getInt("prestige",0); st.pickTier=s.getInt("pickTier",0); st.pickPrestige=s.getInt("pickPrestige",0); st.shovelLevel=s.getInt("shovelLevel",0); st.shovelXp=s.getLong("shovelXp",0); st.shovelTier=s.getInt("shovelTier",0); st.shovelPrestige=s.getInt("shovelPrestige",0); st.axeLevel=s.getInt("axeLevel",0); st.axeXp=s.getLong("axeXp",0); st.axeTier=s.getInt("axeTier",0); st.axePrestige=s.getInt("axePrestige",0); if(!s.contains("pickTier")){st.pickLevel=0;st.pickXp=0;st.pickTier=0;st.pickPrestige=0;} st.money=s.getDouble("money",0); st.blocks=s.getLong("blocks",0); st.name=s.getString("name", id); stats.put(UUID.fromString(id),st);
        } catch (IllegalArgumentException ignored) { }
        if (!playersData.getBoolean("meta.pickaxe-prestige-cycle-migration", false)) {
            stats.values().forEach(st -> st.pickPrestige = Math.max(0, st.pickPrestige / 6));
            playersData.set("meta.pickaxe-prestige-cycle-migration", true);
            saveStats();
            getLogger().info("Skorygowano prestiż kilofa: od teraz 1 prestiż = 1 pełny obieg materiałów.");
        }
    }
    private void saveStats() {
        for (Map.Entry<UUID, ItemStack[]> entry : toolVaults.entrySet()) { for (int i=0;i<9;i++) playersData.set("tool-vault."+entry.getKey()+"."+i, entry.getValue()[i]); }
        playersData.set("players", null);
        stats.forEach((id,s)->{ String p="players."+id+"."; playersData.set(p+"name",s.name); playersData.set(p+"level",s.level); playersData.set(p+"xp",s.xp); playersData.set(p+"pickLevel",s.pickLevel); playersData.set(p+"pickXp",s.pickXp); playersData.set(p+"pickTier",s.pickTier); playersData.set(p+"pickPrestige",s.pickPrestige); playersData.set(p+"shovelLevel",s.shovelLevel); playersData.set(p+"shovelXp",s.shovelXp); playersData.set(p+"shovelTier",s.shovelTier); playersData.set(p+"shovelPrestige",s.shovelPrestige); playersData.set(p+"axeLevel",s.axeLevel); playersData.set(p+"axeXp",s.axeXp); playersData.set(p+"axeTier",s.axeTier); playersData.set(p+"axePrestige",s.axePrestige); playersData.set(p+"prestige",s.prestige); playersData.set(p+"money",s.money); playersData.set(p+"blocks",s.blocks); });
        try { playersData.save(playersFile); } catch(IOException e){getLogger().severe("Nie mozna zapisac players.yml: "+e.getMessage());}
    }
    private void loadMines() {
        ConfigurationSection root=minesData.getConfigurationSection("mines"); if(root==null)return;
        for(String key:root.getKeys(false)) { ConfigurationSection s=root.getConfigurationSection(key); if(s==null)continue; try {
            Mine m=new Mine(key); m.world=s.getString("world"); m.x1=s.getInt("region.pos1.x",s.getInt("x1"));m.y1=s.getInt("region.pos1.y",s.getInt("y1"));m.z1=s.getInt("region.pos1.z",s.getInt("z1"));m.x2=s.getInt("region.pos2.x",s.getInt("x2"));m.y2=s.getInt("region.pos2.y",s.getInt("y2"));m.z2=s.getInt("region.pos2.z",s.getInt("z2"));m.mode=s.getString("mode","region");m.money=s.getDouble("rewards.money",s.getDouble("money",1));m.playerXp=s.getInt("rewards.player-xp",s.getInt("playerXp",1));m.pickXp=s.getInt("rewards.pickaxe-xp",s.getInt("pickXp",1));m.regenSeconds=s.getInt("regeneration.seconds",s.getInt("regenSeconds",300));m.boundaryParticles=s.getBoolean("visuals.boundary-particles",false);m.requiredTool=s.getString("required-tool","PICKAXE").toUpperCase(Locale.ROOT);m.hologramLines=new ArrayList<>(s.getStringList("hologram.lines"));if(m.hologramLines.isEmpty())m.hologramLines=new ArrayList<>(getConfig().getStringList("holograms.default-lines"));if(m.hologramLines.isEmpty())m.hologramLines=new ArrayList<>(List.of("&6Kopalnia: &e{name}","&7Bloki: &f{blocks}","&bOdnowienie: &f{regen}"));
            for(String mat:s.getStringList("allowed-blocks"))try{m.allowed.add(Material.valueOf(mat));}catch(IllegalArgumentException ignored){}
            if(m.allowed.isEmpty())for(String mat:s.getStringList("blocks"))try{m.allowed.add(Material.valueOf(mat));}catch(IllegalArgumentException ignored){}
            loadSnapshot(m); if(m.snapshot.isEmpty()){for(String line:s.getStringList("snapshot")){String[] pair=line.split(";",2);if(pair.length==2)m.snapshot.put(pair[0],pair[1]);}if(!m.snapshot.isEmpty())saveSnapshot(m);} mines.put(key.toLowerCase(Locale.ROOT),m);
        } catch(Exception e){getLogger().warning("Nie mozna wczytac kopalni "+key+": "+e.getMessage());} }
    }
    private void saveMines() {
        minesData.set("mines",null); mines.forEach((key,m)->{String p="mines."+key+"."; minesData.set(p+"world",m.world);minesData.set(p+"region.pos1.x",m.x1);minesData.set(p+"region.pos1.y",m.y1);minesData.set(p+"region.pos1.z",m.z1);minesData.set(p+"region.pos2.x",m.x2);minesData.set(p+"region.pos2.y",m.y2);minesData.set(p+"region.pos2.z",m.z2);minesData.set(p+"mode",m.mode);minesData.set(p+"rewards.money",m.money);minesData.set(p+"rewards.player-xp",m.playerXp);minesData.set(p+"rewards.pickaxe-xp",m.pickXp);minesData.set(p+"regeneration.seconds",m.regenSeconds);minesData.set(p+"visuals.boundary-particles",m.boundaryParticles);minesData.set(p+"required-tool",m.requiredTool);minesData.set(p+"hologram.lines",m.hologramLines);minesData.set(p+"allowed-blocks",m.allowed.stream().map(Enum::name).toList());saveSnapshot(m);});
        try{minesData.save(minesFile);}catch(IOException e){getLogger().severe("Nie mozna zapisac mines.yml: "+e.getMessage());}
    }
    private File snapshotFile(Mine m){File dir=new File(getDataFolder(),"snapshots");if(!dir.exists())dir.mkdirs();return new File(dir,m.name.toLowerCase(Locale.ROOT)+".dat");}
    private void saveSnapshot(Mine m){File f=snapshotFile(m);try(DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new GZIPOutputStream(new java.io.FileOutputStream(f))))){out.writeInt(m.snapshot.size());for(var e:m.snapshot.entrySet()){out.writeUTF(e.getKey());out.writeUTF(e.getValue());}}catch(IOException ex){getLogger().warning("Nie mozna zapisac snapshotu kopalni "+m.name+": "+ex.getMessage());}}
    private void loadSnapshot(Mine m){File f=snapshotFile(m);if(!f.exists())return;try(DataInputStream in=new DataInputStream(new BufferedInputStream(new GZIPInputStream(new java.io.FileInputStream(f))))){int count=in.readInt();if(count<0||count>250000)return;for(int i=0;i<count;i++)m.snapshot.put(in.readUTF(),in.readUTF());}catch(IOException ex){getLogger().warning("Nie mozna wczytac snapshotu kopalni "+m.name+": "+ex.getMessage());}}
    private Stats stat(Player p){Stats s=stats.computeIfAbsent(p.getUniqueId(),k->new Stats());s.name=p.getName();return s;}
    private String lang(String key, String fallback) { return lang == null ? fallback : lang.getString(key, fallback); }
    private void msg(CommandSender s,String t){
        String prefix=lang("prefix", "&8[&bMine&fProgress&8] &r");
        // lang.yml allows custom prefix and exact-message overrides without breaking dynamic arguments.
        if(lang!=null){String override=lang.getString("overrides."+Integer.toHexString(t.hashCode()));if(override!=null)t=override;}
        s.sendMessage(ChatColor.translateAlternateColorCodes('&', prefix+"&7› &r"+t));
    }
    private void prestigeEffect(Player p, String toolName) {
        Location loc=p.getLocation().add(0,1,0);
        p.getWorld().spawnParticle(Particle.TOTEM_OF_UNDYING,loc,55,0.55,0.8,0.55,0.08);
        p.getWorld().spawnParticle(Particle.FIREWORK,loc,35,0.45,0.65,0.45,0.03);
        p.playSound(p.getLocation(),Sound.UI_TOAST_CHALLENGE_COMPLETE,1.0f,1.0f);
        p.playSound(p.getLocation(),Sound.ENTITY_PLAYER_LEVELUP,0.75f,1.25f);
        String title=lang("prestige.title", "&6✦ PRESTIŻ! &e✦").replace("{tool}",toolName);
        String subtitle=lang("prestige.subtitle", "&7Ukończono pełny obieg: &f{tool}").replace("{tool}",toolName);
        p.sendTitle(ChatColor.translateAlternateColorCodes('&',title),ChatColor.translateAlternateColorCodes('&',subtitle),10,55,15);
        for(Player viewer:p.getWorld().getPlayers()) if(!viewer.equals(p)&&viewer.getLocation().distanceSquared(p.getLocation())<=36){
            viewer.playSound(p.getLocation(),Sound.UI_TOAST_CHALLENGE_COMPLETE,0.6f,1.1f);
            viewer.sendMessage(ChatColor.translateAlternateColorCodes('&',lang("prestige.broadcast","&8✦ &e{player} &7osiągnął prestiż narzędzia: &b{tool}&7!").replace("{player}",p.getName()).replace("{tool}",toolName)));
        }
    }
    private boolean inMine(Block b,Mine m){return b.getWorld().getName().equals(m.world)&&b.getX()>=Math.min(m.x1,m.x2)&&b.getX()<=Math.max(m.x1,m.x2)&&b.getY()>=Math.min(m.y1,m.y2)&&b.getY()<=Math.max(m.y1,m.y2)&&b.getZ()>=Math.min(m.z1,m.z2)&&b.getZ()<=Math.max(m.z1,m.z2);}
    private Mine mineAt(Block b){for(Mine m:mines.values())if(inMine(b,m))return m;return null;}
    private void snapshot(Mine m){World w=Bukkit.getWorld(m.world);if(w==null)return;m.snapshot.clear();int count=0;for(int x=Math.min(m.x1,m.x2);x<=Math.max(m.x1,m.x2);x++)for(int y=Math.min(m.y1,m.y2);y<=Math.max(m.y1,m.y2);y++)for(int z=Math.min(m.z1,m.z2);z<=Math.max(m.z1,m.z2);z++){if(++count>250000){msg(Bukkit.getConsoleSender(),"Kopalnia "+m.name+" przekracza limit snapshotu 250000 blokow.");return;}Block b=w.getBlockAt(x,y,z);if(m.mode.equalsIgnoreCase("blocks")&&!m.allowed.contains(b.getType()))continue;m.snapshot.put(x+","+y+","+z,b.getBlockData().getAsString());}}
    private void regenerate(Mine m){World w=Bukkit.getWorld(m.world);if(w==null)return;for(var e:m.snapshot.entrySet()){String[] xyz=e.getKey().split(",");try{Block b=w.getBlockAt(Integer.parseInt(xyz[0]),Integer.parseInt(xyz[1]),Integer.parseInt(xyz[2])); b.setBlockData(Bukkit.createBlockData(e.getValue()),false);}catch(Exception ignored){}}m.regenAt=0;regenTasks.remove(m.name.toLowerCase(Locale.ROOT));updateHologramText(m);} 
    private void restartMine(Mine m){BukkitTask task=regenTasks.remove(m.name.toLowerCase(Locale.ROOT));if(task!=null)task.cancel();regenerate(m);}
    private void startVisualTasks(){
        cleanupTaggedHolograms();
        // Granice kopalń są rysowane tylko dla kopalń z włączoną opcją.
        boundaryTask=Bukkit.getScheduler().runTaskTimer(this,()->{for(Mine m:mines.values())if(m.boundaryParticles){World w=Bukkit.getWorld(m.world);if(w==null)continue;drawBoundary(w,m);}},10L,10L);
        hologramTask=Bukkit.getScheduler().runTaskTimer(this,()->{for(Mine m:mines.values()){ensureHolograms(m);updateHologramText(m);}},20L,20L);
        Bukkit.getScheduler().runTask(this,()->{for(Mine m:mines.values())ensureHolograms(m);});
    }
    private void cleanupTaggedHolograms(){for(World world:Bukkit.getWorlds())for(Entity entity:world.getEntities())if(entity instanceof ArmorStand stand&&stand.getScoreboardTags().stream().anyMatch(t->t.startsWith("mineprogress_holo_")))stand.remove();}
    private void drawBoundary(World w,Mine m){
        int minX=Math.min(m.x1,m.x2),maxX=Math.max(m.x1,m.x2),minY=Math.min(m.y1,m.y2),maxY=Math.max(m.y1,m.y2),minZ=Math.min(m.z1,m.z2),maxZ=Math.max(m.z1,m.z2);
        int step=Math.max(1,getConfig().getInt("visuals.boundary-step",2));
        // Dwanaście krawędzi prostopadłościanu zamiast całych ścian — mniej particle.
        for(int y:new int[]{minY,maxY}){for(int x=minX;x<=maxX;x+=step){particle(w,x,y,minZ);particle(w,x,y,maxZ);}for(int z=minZ;z<=maxZ;z+=step){particle(w,minX,y,z);particle(w,maxX,y,z);}}
        for(int x:new int[]{minX,maxX})for(int z:new int[]{minZ,maxZ})for(int y=minY;y<=maxY;y+=step)particle(w,x,y,z);
    }
    private void particle(World w,int x,int y,int z){w.spawnParticle(Particle.END_ROD,x+0.5,y+0.5,z+0.5,1,0,0,0,0);}
    private String hologramTag(Mine m){return "mineprogress_holo_"+m.name.toLowerCase(Locale.ROOT);}
    private void removeHolograms(Mine m){for(ArmorStand stand:new ArrayList<>(m.holograms))if(stand!=null&&!stand.isDead())stand.remove();m.holograms.clear();World w=Bukkit.getWorld(m.world);if(w!=null)for(Entity entity:w.getEntities())if(entity instanceof ArmorStand stand&&stand.getScoreboardTags().contains(hologramTag(m)))stand.remove();}
    private void ensureHolograms(Mine m){
        World w=Bukkit.getWorld(m.world);if(w==null)return;int count=Math.max(1,m.hologramLines.size());
        boolean valid=m.holograms.size()==count&&m.holograms.stream().allMatch(a->a!=null&&a.isValid());
        if(valid)return;removeHolograms(m);double x=(Math.min(m.x1,m.x2)+Math.max(m.x1,m.x2)+1)/2.0,z=(Math.min(m.z1,m.z2)+Math.max(m.z1,m.z2)+1)/2.0,y=Math.max(m.y1,m.y2)+getConfig().getDouble("holograms.height",1.8);String tag=hologramTag(m);
        for(int i=0;i<count;i++){final int line=i;ArmorStand stand=w.spawn(new Location(w,x,y-i*getConfig().getDouble("holograms.line-spacing",0.27),z),ArmorStand.class,a->{a.setInvisible(true);a.setMarker(true);a.setGravity(false);a.setSmall(true);a.setCustomNameVisible(true);a.setPersistent(true);a.setInvulnerable(true);a.addScoreboardTag(tag);a.setCustomName(" ");});m.holograms.add(stand);}updateHologramText(m);
    }
    private String mineBlocksText(Mine m){if(m.mode.equalsIgnoreCase("blocks")&&!m.allowed.isEmpty())return m.allowed.stream().map(Material::name).sorted().limit(5).toList().toString();Set<String> types=new TreeSet<>();for(String data:m.snapshot.values()){String type=data.split("\\[",2)[0];if(type.contains(":"))type=type.substring(type.indexOf(":")+1);types.add(type.toUpperCase(Locale.ROOT));if(types.size()>=5)break;}return types.isEmpty()?"Bloki w regionie":String.join(", ",types);}
    private String requiredToolDisplay(String raw){String req=raw==null?"PICKAXE":raw.toUpperCase(Locale.ROOT);String[] parts=req.split("_");String mat=parts.length>1?parts[0]:"DOWOLNY";String kind=parts[parts.length-1];String material=switch(mat){case "WOODEN"->"drewniany";case "STONE"->"kamienny";case "IRON"->"żelazny";case "GOLDEN"->"złoty";case "DIAMOND"->"diamentowy";case "NETHERITE"->"netherytowy";default->"dowolny";};String tool=switch(kind){case "PICKAXE"->"kilof";case "SHOVEL"->"łopata";case "AXE"->"siekiera";default->"narzędzie";};return mat.equals("DOWOLNY")?"dowolny specjalny "+tool:material+" "+tool;}
    private void updateHologramText(Mine m){if(m.holograms.isEmpty())return;String blocks=mineBlocksText(m);for(int i=0;i<m.holograms.size()&&i<m.hologramLines.size();i++){ArmorStand a=m.holograms.get(i);if(a==null||!a.isValid())continue;String line=m.hologramLines.get(i).replace("{name}",m.name).replace("{blocks}",blocks).replace("{regen}",formatRemaining(m)).replace("{tool}",requiredToolDisplay(m.requiredTool)).replace("{world}",m.world);a.setCustomName(ChatColor.translateAlternateColorCodes('&',line));}}
    private void deleteMine(Mine m){BukkitTask task=regenTasks.remove(m.name.toLowerCase(Locale.ROOT));if(task!=null)task.cancel();removeHolograms(m);mines.remove(m.name.toLowerCase(Locale.ROOT));File snap=snapshotFile(m);if(snap.exists()&&!snap.delete())getLogger().warning("Nie można usunąć snapshotu kopalni "+m.name);saveMines();}
    private ItemStack[] vault(UUID id) {
        return toolVaults.computeIfAbsent(id, key -> { ItemStack[] items=new ItemStack[9]; for(int i=0;i<9;i++) items[i]=playersData.getItemStack("tool-vault."+key+"."+i); return items; });
    }
    private boolean vaultHasTool(UUID id, String tool) { for(ItemStack item:vault(id)) if(isSpecialTool(item,tool)) return true; return false; }
    private void openVault(Player p) { Inventory inv=Bukkit.createInventory(new MenuHolder(MenuType.VAULT,null),9,ChatColor.DARK_GRAY+"MineProgress | Schowek narzędzi"); ItemStack[] stored=vault(p.getUniqueId()); for(int i=0;i<9;i++) if(stored[i]!=null) inv.setItem(i,stored[i].clone()); p.openInventory(inv); msg(p,"&7W schowku można przechowywać wyłącznie narzędzia MineProgress. Wyjmij je komendą &e/wyciagnij <kilof|lopata|siekiera>&7."); }
    private void saveVaultFrom(Inventory inv, UUID id) { ItemStack[] stored=new ItemStack[9]; for(int i=0;i<9;i++){ ItemStack item=inv.getItem(i); if(item!=null && !item.getType().isAir() && isMineProgressTool(item)) stored[i]=item.clone(); } toolVaults.put(id,stored); saveStats(); }
    private void extractTool(Player p, String tool) { ItemStack[] stored=vault(p.getUniqueId()); for(int i=0;i<stored.length;i++){ ItemStack item=stored[i]; if(isSpecialTool(item,tool) && ownedBy(item,p)){ Map<Integer,ItemStack> left=p.getInventory().addItem(item.clone()); if(!left.isEmpty()){msg(p,"&cBrak miejsca w ekwipunku. Zwolnij slot i spróbuj ponownie."); return;} stored[i]=null; toolVaults.put(p.getUniqueId(),stored); saveStats(); msg(p,"&aWyjęto narzędzie: &f"+toolLabel(tool)+"&a."); return; } } msg(p,"&cNie masz tego narzędzia w schowku. Użyj /schowaj, aby nim zarządzać."); }
    private String toolLabel(String tool){return tool.equals("PICKAXE")?"kilof":tool.equals("SHOVEL")?"łopata":"siekiera";}

    @EventHandler public void onJoin(PlayerJoinEvent e){Player p=e.getPlayer();Stats st=stat(p);for(String tool:List.of("PICKAXE","SHOVEL","AXE")){int found=0;for(int slot=0;slot<p.getInventory().getSize();slot++){ItemStack it=p.getInventory().getItem(slot);if(!isSpecialTool(it,tool))continue;if(!ownedBy(it,p)||found++>0){p.getInventory().setItem(slot,null);continue;}if(tool.equals("PICKAXE"))applyPickaxeState(it,st);else applyToolState(it,st,tool);p.getInventory().setItem(slot,it);}ItemStack off=p.getInventory().getItemInOffHand();if(isSpecialTool(off,tool)){if(!ownedBy(off,p)||found>0)p.getInventory().setItemInOffHand(null);else{if(tool.equals("PICKAXE"))applyPickaxeState(off,st);else applyToolState(off,st,tool);p.getInventory().setItemInOffHand(off);found++;}}if(found==0 && !vaultHasTool(p.getUniqueId(),tool)){ItemStack item=tool.equals("PICKAXE")?makePickaxe():makeTool(tool);if(tool.equals("PICKAXE"))applyPickaxeState(item,st);else applyToolState(item,st,tool);Map<Integer,ItemStack> left=p.getInventory().addItem(item);if(!left.isEmpty())msg(p,"&cZwolnij miejsce w ekwipunku — narzędzie MineProgress nie zostało wydane.");}}saveStats();}
    @EventHandler public void onRespawn(PlayerRespawnEvent e){Bukkit.getScheduler().runTask(this,()->{Player p=e.getPlayer();Stats st=stat(p);syncPickaxes(p,st);syncTool(p,st,"SHOVEL");syncTool(p,st,"AXE");for(String tool:List.of("PICKAXE","SHOVEL","AXE")){boolean found=false;for(ItemStack it:p.getInventory().getContents())if(isSpecialTool(it,tool)&&ownedBy(it,p)){found=true;break;}if(!found){ItemStack it=tool.equals("PICKAXE")?makePickaxe():makeTool(tool);if(tool.equals("PICKAXE"))applyPickaxeState(it,st);else applyToolState(it,st,tool);p.getInventory().addItem(it);}}});}
    @EventHandler public void onHeld(PlayerItemHeldEvent e){Bukkit.getScheduler().runTask(this,()->syncPickaxes(e.getPlayer(),stat(e.getPlayer())));}
    @EventHandler public void onSwap(PlayerSwapHandItemsEvent e){Bukkit.getScheduler().runTask(this,()->syncPickaxes(e.getPlayer(),stat(e.getPlayer())));}
    @EventHandler public void onBreak(BlockBreakEvent e){
        Player p=e.getPlayer(); Block b=e.getBlock(); Mine m=mineAt(b); if(m==null)return;
        if(m.mode.equalsIgnoreCase("blocks")&&!m.allowed.contains(b.getType())){e.setCancelled(true);return;}
        ItemStack hand=p.getInventory().getItemInMainHand();
        if(!mineToolMatches(hand,m,p)){e.setCancelled(true);msg(p,"Do tej kopalni potrzebujesz narzędzia MineProgress: "+m.requiredTool+".");return;}
        Stats s=stat(p); s.blocks++; s.xp+=m.playerXp;
        String usedTool=isSpecialShovel(hand)?"SHOVEL":isSpecialAxe(hand)?"AXE":"PICKAXE";
        if(usedTool.equals("PICKAXE"))s.pickXp+=m.pickXp;else if(usedTool.equals("SHOVEL"))s.shovelXp+=m.pickXp;else s.axeXp+=m.pickXp;
        levelUp(s); syncPickaxes(p,s); syncTool(p,s,"SHOVEL"); syncTool(p,s,"AXE");
        MiningStreak streak=miningStreaks.computeIfAbsent(p.getUniqueId(),k->new MiningStreak());
        long now=System.currentTimeMillis(); long streakTimeout=Math.max(1,getConfig().getLong("mining-streak.timeout-seconds",10))*1000L; if(now-streak.lastAt<=streakTimeout)streak.count++;else streak.count=1; streak.lastAt=now;
        int blocksPerStep=Math.max(1,getConfig().getInt("mining-streak.blocks-per-step",10)); double bonusPerStep=Math.max(0,getConfig().getDouble("mining-streak.money-bonus-per-step",0.02)); double maxBonus=Math.max(0,getConfig().getDouble("mining-streak.max-bonus",0.20)); int maxSteps=bonusPerStep<=0?0:(int)Math.floor(maxBonus/bonusPerStep); int bonusSteps=Math.min(maxSteps,streak.count/blocksPerStep); double comboBonus=Math.min(maxBonus,bonusSteps*bonusPerStep);
        if(economy!=null){int toolPrestige=usedTool.equals("SHOVEL")?s.shovelPrestige:usedTool.equals("AXE")?s.axePrestige:s.pickPrestige;double toolPrestigeRate=usedTool.equals("PICKAXE")?getConfig().getDouble("settings.pickaxe-prestige-money-bonus",0.0025):getConfig().getDouble("settings.tool-prestige-money-bonus",0.0025);double pay=m.money*(1.0+s.prestige*getConfig().getDouble("settings.prestige-bonus-per-level",0.005)+toolPrestige*toolPrestigeRate+Math.max(0,s.level-1)*getConfig().getDouble("settings.player-level-money-bonus",0.001))*(1.0+comboBonus);economy.depositPlayer(p,pay);s.money+=pay;}
        if(streak.count>0&&streak.count%blocksPerStep==0){p.sendActionBar(ChatColor.GOLD+"✦ Seria wydobycia: "+ChatColor.YELLOW+streak.count+ChatColor.GRAY+" bloków • "+ChatColor.GREEN+"+"+(int)(comboBonus*100)+"% monet");}
        if(usedTool.equals("PICKAXE"))bonusOreDrop(p,b,s);
        if(m.regenAt==0){m.regenAt=System.currentTimeMillis()+m.regenSeconds*1000L;String k=m.name.toLowerCase(Locale.ROOT);BukkitTask old=regenTasks.remove(k);if(old!=null)old.cancel();regenTasks.put(k,Bukkit.getScheduler().runTaskLater(this,()->regenerate(m),Math.max(1,m.regenSeconds)*20L));}
    }
    private boolean isSpecialPickaxe(ItemStack item){return item!=null&&item.getType().name().endsWith("_PICKAXE")&&item.hasItemMeta()&&item.getItemMeta().getPersistentDataContainer().has(pickaxeKey,PersistentDataType.BYTE);}
    private boolean isSpecialShovel(ItemStack item){return item!=null&&item.getType().name().endsWith("_SHOVEL")&&item.hasItemMeta()&&item.getItemMeta().getPersistentDataContainer().has(shovelKey,PersistentDataType.BYTE);}
    private boolean isSpecialAxe(ItemStack item){return item!=null&&item.getType().name().endsWith("_AXE")&&!item.getType().name().endsWith("_PICKAXE")&&item.hasItemMeta()&&item.getItemMeta().getPersistentDataContainer().has(axeKey,PersistentDataType.BYTE);}
    private NamespacedKey toolKey(String tool){return tool.equals("SHOVEL")?shovelKey:tool.equals("AXE")?axeKey:pickaxeKey;}
    private int toolTier(Stats s,String tool){return tool.equals("SHOVEL")?s.shovelTier:tool.equals("AXE")?s.axeTier:s.pickTier;}
    private int toolLevel(Stats s,String tool){return tool.equals("SHOVEL")?s.shovelLevel:tool.equals("AXE")?s.axeLevel:s.pickLevel;}
    private long toolXp(Stats s,String tool){return tool.equals("SHOVEL")?s.shovelXp:tool.equals("AXE")?s.axeXp:s.pickXp;}
    private int toolMax(String tool){return Math.max(1,getConfig().getInt("settings.max-"+tool.toLowerCase(Locale.ROOT)+"-level",tool.equals("PICKAXE")?20:5));}
    private long toolXpRequired(String tool,int level){long base=Math.max(1,getConfig().getLong("settings."+tool.toLowerCase(Locale.ROOT)+"-xp-base",tool.equals("PICKAXE")?10:25));long increase=Math.max(0,getConfig().getLong("settings."+tool.toLowerCase(Locale.ROOT)+"-xp-increase-per-level",tool.equals("PICKAXE")?2:10));return base+increase*Math.max(0,level);}
    private Material materialForTool(String tool,int tier){tier=Math.max(0,Math.min(5,tier));return switch(tool){case "SHOVEL"->new Material[]{Material.WOODEN_SHOVEL,Material.STONE_SHOVEL,Material.IRON_SHOVEL,Material.GOLDEN_SHOVEL,Material.DIAMOND_SHOVEL,Material.NETHERITE_SHOVEL}[tier];case "AXE"->new Material[]{Material.WOODEN_AXE,Material.STONE_AXE,Material.IRON_AXE,Material.GOLDEN_AXE,Material.DIAMOND_AXE,Material.NETHERITE_AXE}[tier];default->pickaxeMaterial(tier);};}
    private boolean isSpecialTool(ItemStack item,String tool){return switch(tool){case "SHOVEL"->isSpecialShovel(item);case "AXE"->isSpecialAxe(item);default->isSpecialPickaxe(item);};}
    private ItemStack makeTool(String tool){ItemStack item=new ItemStack(materialForTool(tool,tool.equals("PICKAXE")?0:0));ItemMeta meta=item.getItemMeta();meta.getPersistentDataContainer().set(toolKey(tool),PersistentDataType.BYTE,(byte)1);item.setItemMeta(meta);return item;}
    private String stOwnerId(Stats st){for(Map.Entry<UUID,Stats> e:stats.entrySet())if(e.getValue()==st)return e.getKey().toString();return "";}
    private boolean ownedBy(ItemStack item,Player p){if(item==null||!item.hasItemMeta())return false;String owner=item.getItemMeta().getPersistentDataContainer().get(ownerKey,PersistentDataType.STRING);return owner==null||owner.isBlank()||owner.equals(p.getUniqueId().toString());}
